import * as T from './three.module.js';
import {tailPaint} from './scenery.js';
const material=(color,roughness=.45,metalness=.1)=>new T.MeshStandardMaterial({color,roughness,metalness});
function add(p,g,m,x=0,y=0,z=0){const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;p.add(o);return o;}
function box(p,w,h,d,m,x,y,z){return add(p,new T.BoxGeometry(w,h,d),m,x,y,z);}
function tube(p,points,r,m){return add(p,new T.TubeGeometry(new T.CatmullRomCurve3(points.map(a=>new T.Vector3(...a))),24,r,6,false),m);}
function lathe(p,points,m,x=0,y=0,z=0){const g=new T.LatheGeometry(points.map(a=>new T.Vector2(...a)),48);g.rotateX(Math.PI/2);return add(p,g,m,x,y,z);}
function skin(isA){const c=document.createElement('canvas');c.width=4096;c.height=2048;const ctx=c.getContext('2d');ctx.fillStyle=isA?'#f4f5f4':'#20a0d1';ctx.fillRect(0,0,c.width,c.height);
 // Underside, seam lines, doors and two properly spaced decks.
 ctx.fillStyle=isA?'#dbe0e2':'#e6e9eb';ctx.fillRect(0,1150,4096,730);ctx.strokeStyle='#dce0e2';ctx.lineWidth=1;
 for(let x=200;x<4000;x+=138){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,2048);ctx.stroke();}
 for(const side of [0,1]){ctx.save();if(side===1){ctx.translate(0,3072);ctx.scale(1,-1);}const base=1940;const rows=isA?[base-54,base-190]:[base-42];for(const y of rows){for(let n=0;n<39;n++){const x=670+n*66;if([1,11,22,33].includes(n))continue;ctx.fillStyle='#8b989f';ctx.fillRect(x-2,y-2,22,29);ctx.fillStyle='#183341';ctx.fillRect(x,y,18,25);ctx.fillStyle='#6d929e';ctx.fillRect(x+2,y+2,14,4);}}
 if(!isA){for(let n=0;n<12;n++){ctx.fillStyle='#163846';ctx.fillRect(720+n*58,base-168,18,24);}}
 for(const x of [650,1380,2110,2830,3280]){ctx.strokeStyle=isA?'#85949c':'#dceef5';ctx.lineWidth=3;ctx.strokeRect(x,base-76,48,102);if(isA)ctx.strokeRect(x,base-210,48,99);ctx.fillStyle='#b33e3b';ctx.fillRect(x+30,base-23,11,3);}
 ctx.fillStyle=isA?'#a27f35':'#ffffff';ctx.font=isA?'bold 155px Georgia':'bold 170px Arial';ctx.save();if(side===0){ctx.translate(2750,0);ctx.scale(-1,1);}ctx.fillText(isA?'EMIRATES':'KLM',900,base+80);ctx.restore();ctx.font='26px Arial';ctx.fillStyle='#334650';ctx.fillText(isA?'AIRBUS A380-800   A6-EDH':'BOEING 747-400   PH-BFL',2660,base+30);ctx.restore();
 }
 const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.anisotropy=8;return t;}
export function buildAirliner(type){const isA=type==='a380';const root=new T.Group(),fans=[],gear=[];const white=material('#f2f4f5',.26,.18),wing=material('#cbd2d8',.3,.3),chrome=material('#b5c1cd',.24,.7),dark=material('#18232c',.6),rubber=material('#17191c',.95),glass=new T.MeshPhysicalMaterial({color:'#142c3c',roughness:.12,metalness:.35,clearcoat:1,envMapIntensity:1.4,side:T.DoubleSide});const paint=new T.MeshPhysicalMaterial({map:skin(isA),roughness:.31,metalness:.05,clearcoat:.65,clearcoatRoughness:.23,envMapIntensity:.7});
 const stations=isA?[[-36.4,0,0,-.4],[-35.5,1,1,-.3],[-33,2.4,2.5,0],[-29,3.3,3.8,0],[-23,3.57,4.14,0],[16,3.57,4.14,0],[24,2.8,3.2,.35],[31,1.45,1.65,.9],[36,.05,.05,1.3]]:[[-35.3,0,0,0],[-34,1.5,1.3,0],[-30,2.9,3.4,.8],[-25,3.25,4.15,1.1],[-15,3.25,4.0,1.0],[-6,3.25,3.25,.2],[17,3.25,3.2,0],[27,2,2.1,.6],[35,.03,.04,1.5]];
 const curves=[1,2,3].map(k=>new T.SplineCurve(stations.map(s=>new T.Vector2(s[0],s[k]))));const points=curves.map(c=>c.getPoints(120));const positions=[],uv=[],indices=[];for(let i=0;i<=120;i++){for(let j=0;j<=64;j++){const a=j/64*Math.PI*2;positions.push(Math.max(0,points[0][i].y)*Math.cos(a),points[2][i].y+Math.max(0,points[1][i].y)*Math.sin(a),points[0][i].x);uv.push((points[0][i].x+36.4)/72.8,j/64);if(i<120&&j<64){const n=i*65+j;indices.push(n,n+65,n+1,n+1,n+65,n+66);}}}const hull=new T.BufferGeometry();hull.setAttribute('position',new T.Float32BufferAttribute(positions,3));hull.setAttribute('uv',new T.Float32BufferAttribute(uv,2));hull.setIndex(indices.reverse());hull.computeVertexNormals();add(root,hull,paint);
 // Conformal windshield panels follow the actual nose instead of floating boxes.
 function hullPoint(z,angle,side){let i=0;while(i<119&&points[0][i+1].x<z)i++;const t=T.MathUtils.clamp((z-points[0][i].x)/(points[0][i+1].x-points[0][i].x),0,1);const rx=T.MathUtils.lerp(points[0][i].y,points[0][i+1].y,t)+.045,ry=T.MathUtils.lerp(points[1][i].y,points[1][i+1].y,t)+.045,cy=T.MathUtils.lerp(points[2][i].y,points[2][i+1].y,t);return [side*rx*Math.cos(angle),cy+ry*Math.sin(angle),z];}
 for(const side of [-1,1]){for(const [z0,z1,lo,hi] of [[-33.1,-31.9,.62,1.46],[-31.75,-30.15,.49,.87],[-30,-28.8,.42,.72]]){const shift=isA?0:.25;const verts=[];const faces=[];for(let j=0;j<=4;j++)for(let i=0;i<=5;i++){verts.push(...hullPoint(z0+(z1-z0)*i/5,lo+shift+(hi-lo)*j/4,side));if(j<4&&i<5){const n=j*6+i;faces.push(n,n+1,n+6,n+1,n+7,n+6);}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(verts,3));g.setIndex(faces);g.computeVertexNormals();add(root,g,glass);const edge=[hullPoint(z0,lo+shift,side),hullPoint(z1,lo+shift,side),hullPoint(z1,hi+shift,side),hullPoint(z0,hi+shift,side),hullPoint(z0,lo+shift,side)];tube(root,edge,.035,chrome);}}
 // Radome joint, APU outlet and navigation hardware.
 const noseRing=[];for(let k=0;k<=64;k++)noseRing.push(hullPoint(isA?-33.5:-33.7,k/64*Math.PI*2,1));tube(root,noseRing,.012,material('#9da7ae',.6));
 lathe(root,[[.18,35.8],[.24,36.1],[.18,36.35]],dark,0,1.3,0);
 function airfoil(side,sections){const pos=[],ind=[];const count=24;for(const [x,z,chord,y,thick] of sections){for(let i=0;i<=count;i++){const a=i/count*Math.PI*2,t=(1-Math.cos(a))/2;pos.push(side*x,y+Math.sin(a)*thick*(1-t*.65),z+t*chord);}}for(let k=0;k<sections.length-1;k++)for(let i=0;i<count;i++){const a=k*(count+1)+i;ind.push(a,a+1,a+count+1,a+1,a+count+2,a+count+1);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setIndex(side===1?ind:ind.reverse());g.computeVertexNormals();const m=wing.clone();m.side=T.DoubleSide;add(root,g,m);}
 for(const side of [-1,1]){const span=isA?39.8:32.3;airfoil(side,[[2,-13,24,-1.6,.85],[8,-10,19,-1.3,.65],[16,-4,13,-.4,.42],[27,5,7,1.0,.22],[span,12,2.8,2.4,.08]]);airfoil(side,[[1.8,23,10,1.2,.35],[7,26,7,2,.22],[16,32,3,3,.08]]);
 tube(root,[[side*3,-.9,-12.8],[side*8,-.67,-9.9],[side*16,0,-3.9],[side*27,1.2,5.1],[side*span,2.5,12.05]],.07,chrome);
 for(let k=0;k<3;k++){const x=8+k*8,z=4+k*3;tube(root,[[side*x,-.75+k*.7,z],[side*(x+6),-.25+k*.7,z+2.6]],.025,dark);const fair=add(root,new T.SphereGeometry(1,18,10),white,side*(x+1),-2+k*.5,z+3);fair.scale.set(.38,.4,3);}
 const finTip=new T.Shape();finTip.moveTo(0,0);finTip.lineTo(.6,isA?1.7:3.5);finTip.lineTo(1.5,isA?1.55:3.3);finTip.lineTo(2.3,0);finTip.closePath();const tipGeo=new T.ExtrudeGeometry(finTip,{depth:.11,bevelEnabled:true,bevelThickness:.035,bevelSize:.045,bevelSegments:2});tipGeo.rotateY(Math.PI/2);const winglet=add(root,tipGeo,white,side*span,2.4,12);winglet.rotation.z=-side*.19;if(isA){const lower=add(root,tipGeo.clone(),white,side*span,2.4,12);lower.scale.y=-.55;}
 const nav=add(root,new T.SphereGeometry(.18,12,8),new T.MeshBasicMaterial({color:side<0?'#fa3838':'#3aff99'}),side*span,2.6,12);
 for(const [x,z] of [[12,-6],[24,1]]){const engine=new T.Group();root.add(engine);engine.position.set(side*x,-4.45,z);box(engine,.55,2.8,4.5,wing,0,2.0,1.2);const r=isA?1.65:1.4;
 lathe(engine,[[r*.69,2.7],[r*.8,2.7],[r+.02,1.4],[r+.14,-2.5],[r+.12,-3.2],[r,-3.5],[r-.15,-3.1],[r-.2,-2.0]].reverse(),white);lathe(engine,[[r-.12,-3.12],[r-.03,-3.5],[r+.1,-3.3]],chrome);lathe(engine,[[r-.13,-3.1],[r-.22,-1.9]],dark);const fan=new T.Group();fan.position.z=-2.55;engine.add(fan);fans.push(fan);const disk=add(fan,new T.CircleGeometry(r-.19,40),dark);disk.rotation.y=Math.PI;
 for(let k=0;k<28;k++){const sh=new T.Shape();sh.moveTo(.2,.15);sh.quadraticCurveTo(.4,r*.7,.04,r*.86);sh.lineTo(-.11,r*.88);sh.quadraticCurveTo(.17,r*.55,.1,.14);sh.closePath();const blade=add(fan,new T.ShapeGeometry(sh,8),chrome);blade.material.side=T.DoubleSide;blade.rotation.z=k*Math.PI/14;blade.position.z=-.03;}
 lathe(engine,[[0,-3],[.3,-2.85],[.44,-2.45],[.35,-1.9]],chrome);lathe(engine,[[.9,1.8],[.84,3.2],[.27,4.1],[0,4.25]],dark);
 }
 }
 const finShape=new T.Shape();finShape.moveTo(0,19);finShape.lineTo(13.5,28.3);finShape.lineTo(14,31.1);finShape.lineTo(0,32.5);finShape.closePath();const fin=new T.ExtrudeGeometry(finShape,{depth:.55,bevelEnabled:true,bevelThickness:.1,bevelSize:.14,bevelSegments:2,steps:1});const fp=fin.attributes.position,fu=fin.attributes.uv;for(let i=0;i<fp.count;i++){const x=fp.getX(i),y=fp.getY(i),z=fp.getZ(i);fp.setXYZ(i,z-.275,x+2.5,y);fu.setXY(i,(y-19)/13.5,x/14);}fin.computeVertexNormals();add(root,fin,tailPaint(isA));
 const strut=chrome;for(const [x,z,rows] of [[0,-24,1],[-2.4,6,isA?3:2],[2.4,6,isA?3:2],[-5,4,2],[5,4,2]]){const g=new T.Group();g.position.set(x,-3.0,z);root.add(g);gear.push(g);box(g,.24,2.5,.25,strut,0,-1.05,0);tube(g,[[0,.3,1.4],[0,-1.5,-.3]],.1,strut);for(let k=0;k<rows;k++){const zz=(k-(rows-1)/2)*1.25;for(const side of [-1,1]){const tire=add(g,new T.CylinderGeometry(.64,.64,.48,32,1,false),rubber,side*.57,-2.98,zz);tire.rotation.z=Math.PI/2;const wall=add(g,new T.TorusGeometry(.46,.17,8,24),rubber,side*.83,-2.98,zz);wall.rotation.y=Math.PI/2;const hub=add(g,new T.CylinderGeometry(.3,.3,.51,18),strut,side*.57,-2.98,zz);hub.rotation.z=Math.PI/2;}}box(g,1.3,.2,rows*1.35,strut,0,-2.7,0);}
 // Small details whose silhouettes remain readable from the chase camera.
 for(const z of [-11,10])box(root,.13,.7,.8,white,0,4.45,z);const beacon=add(root,new T.SphereGeometry(.18,12,8),new T.MeshBasicMaterial({color:'#e74636'}),0,4.2,0);
 root.position.set(0,7,380);return {root,fans,gear};
}
